  let enemies = v23_recent_visible_enemies_near_point(player, data, pos.x, pos.y, 180000, 40); // 205
  enemies != 0 && enemies >= allies                                    // 206 (m15.ll:52741~52743: `%88 ne 0` && `%88 uge %87`)
}

